// pkg/boundary/sensors/netra_radar.go - NETRA Phased-Array Radar Sensor
//
// Implementation of SensorObserver for the NETRA phased-array radar.
// RF sensors have different characteristics than optical:
// - Longer wavelength (~0.1m vs 550nm)
// - Lower angular resolution but better all-weather capability
// - Higher measurement uncertainty

package sensors

import (
	"fmt"
	"math"

	"ssis/pkg/config"
	"ssis/pkg/gen/axiom_zero/Boundary" // Generated by flatc
	"ssis/pkg/physics"

	zmq "github.com/pebbe/zmq4"
)

// NetraRadar implements SensorObserver for the NETRA phased-array radar
type NetraRadar struct {
	config     config.SensorConfig
	subscriber *zmq.Socket
	latestObs  Observation
	latestCov  [36]float64
	deviceID   uint32
	sampleRate float64
	frequency  float64 // Radar frequency [Hz]
}

// NewNetraRadar creates a new NETRA radar sensor instance
func NewNetraRadar(config config.SensorConfig) (*NetraRadar, error) {
	// Connect to ZMQ SUB socket
	subscriber, err := zmq.NewSocket(zmq.SUB)
	if err != nil {
		return nil, fmt.Errorf("failed to create SUB socket: %w", err)
	}

	err = subscriber.Connect(config.Endpoint)
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to connect to %s: %w", config.Endpoint, err)
	}

	err = subscriber.SetSubscribe("")
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to subscribe: %w", err)
	}

	// NETRA radar frequency (S-band ~3GHz)
	frequency := 3.0e9 // 3 GHz

	return &NetraRadar{
		config:     config,
		subscriber: subscriber,
		deviceID:   2,    // NETRA radar ID
		sampleRate: 50.0, // 50Hz nominal rate (slower than optical)
		frequency:  frequency,
		latestCov:  constructRadarCovariance(),
	}, nil
}

// GetObservation returns the latest observation from NETRA radar
func (n *NetraRadar) GetObservation() (Observation, error) {
	// Read raw bytes from ZMQ (blocking)
	msg, err := n.subscriber.RecvBytes(0)
	if err != nil {
		// Return cached observation if no new data
		return n.latestObs, nil
	}

	// Zero-Copy Read: Cast byte array into FlatBuffer struct
	packet := Boundary.GetRootAsTelemetryPacket(msg, 0)

	// Convert FlatBuffer to Observation
	obs := Observation{
		TimestampNs: packet.TimestampNs(),
		Wavelength:  3.0e8 / n.frequency, // RF wavelength
		DeviceID:    n.deviceID,
		Quality:     0.85, // Good but lower than optical
		Covariance:  n.latestCov,
	}

	// Convert spherical to Cartesian ECI
	az := packet.AzimuthMeasured()
	el := packet.ElevationMeasured()

	// RF has larger angular uncertainty
	obs.Position = physics.Vector3{
		math.Cos(el) * math.Cos(az),
		math.Cos(el) * math.Sin(az),
		math.Sin(el),
	}

	// Velocity from Doppler (placeholder - would use actual Doppler)
	obs.Velocity = physics.Vector3{0, 0, 0}

	n.latestObs = obs
	return obs, nil
}

// GetCovariance returns the radar measurement uncertainty matrix
func (n *NetraRadar) GetCovariance() [36]float64 {
	return n.latestCov
}

// GetWavelength returns the RF wavelength
func (n *NetraRadar) GetWavelength() float64 {
	return 3.0e8 / n.frequency // c/f
}

// GetDeviceID returns the NETRA radar ID
func (n *NetraRadar) GetDeviceID() uint32 {
	return n.deviceID
}

// GetSampleRate returns the radar sample rate
func (n *NetraRadar) GetSampleRate() float64 {
	return n.sampleRate
}

// Close shuts down the ZMQ connection
func (n *NetraRadar) Close() error {
	if n.subscriber != nil {
		return n.subscriber.Close()
	}
	return nil
}

// constructRadarCovariance builds default radar covariance
// RF sensors have lower angular resolution than optical
func constructRadarCovariance() [36]float64 {
	var cov [36]float64

	// Position uncertainty (radar has ~10x worse angular resolution)
	// 50 arcsec = 2.4e-4 rad at 1000km
	posSigma := 2.5e-4 // ~50 arcsec

	// Velocity uncertainty (higher due to Doppler ambiguity)
	velSigma := 1e-4

	// Diagonal elements (variances)
	cov[0] = posSigma * posSigma
	cov[7] = posSigma * posSigma
	cov[14] = posSigma * posSigma
	cov[21] = velSigma * velSigma
	cov[28] = velSigma * velSigma
	cov[35] = velSigma * velSigma

	return cov
}
